import sys
from typing import List, Tuple

def cross_product(p1: Tuple[int, int], p2: Tuple[int, int], p3: Tuple[int, int]) -> int:
    return (p2[0] - p1[0]) * (p3[1] - p2[1]) - (p2[1] - p1[1]) * (p3[0] - p2[0])

def is_left_turn(p1: Tuple[int, int], p2: Tuple[int, int], p3: Tuple[int, int]) -> bool:
    return cross_product(p1, p2, p3) > 0

def is_right_turn(p1: Tuple[int, int], p2: Tuple[int, int], p3: Tuple[int, int]) -> bool:
    return cross_product(p1, p2, p3) < 0

def find_permutation(n: int, points: List[Tuple[int, int]], s: str) -> List[int]:
    # Sort points by their x-coordinate, and by y-coordinate if x-coordinates are equal
    sorted_points = sorted(enumerate(points), key=lambda x: (x[1][0], x[1][1]))

    # Try to construct the permutation
    permutation = []
    used = [False] * n

    def backtrack(index: int) -> bool:
        if index == n:
            return True

        for i in range(n):
            if not used[i]:
                if index == 0:
                    permutation.append(i + 1)
                    used[i] = True
                    if backtrack(index + 1):
                        return True
                    used[i] = False
                else:
                    prev_point = points[sorted_points[permutation[-2] - 1][0]]
                    current_point = points[sorted_points[i][0]]
                    next_point = points[sorted_points[(i + 1) % n][0]]

                    if (s[index - 2] == 'L' and is_left_turn(prev_point, current_point, next_point)) or \
                       (s[index - 2] == 'R' and is_right_turn(prev_point, current_point, next_point)):
                        permutation.append(i + 1)
                        used[i] = True
                        if backtrack(index + 1):
                            return True
                        used[i] = False

    if backtrack(0):
        return permutation
    else:
        return [-1]

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    points = [(int(data[2 * i + 1]), int(data[2 * i + 2])) for i in range(n)]
    s = data[-1]

    result = find_permutation(n, points, s)
    if result == [-1]:
        print(-1)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
